'use strict';

// MODULES //

var serialize = require( '@stdlib/ndarray/base/serialize-meta-data' );
var getData = require( '@stdlib/ndarray/base/data-buffer' );
var addon = require( './../src/addon.node' );


// MAIN //

/**
* Reflect the upper triangular part of a single-precision floating-point matrix `A` into the lower triangular part of another matrix `B`.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a two-dimensional input ndarray corresponding to `A`.
*     -   a two-dimensional output ndarray corresponding to `B`.
*     -   a zero-dimensional ndarray specifying the diagonal below which to ignore.
*
* @private
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {Object} output ndarray
*
* @example
* var Float32Matrix = require( '@stdlib/ndarray/matrix/float32' );
* var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
*
* var A = new Float32Matrix( [ [ 1.0, 2.0 ], [ 3.0, 4.0 ] ] );
* var B = new Float32Matrix( [ [ 0.0, 0.0 ], [ 0.0, 0.0 ] ] );
*
* var k = scalar2ndarray( 0, {
*     'dtype': 'int32'
* });
*
* var out = striu2tril( [ A, B, k ] );
* // returns <ndarray>[ [ 1.0, 0.0 ], [ 2.0, 4.0 ] ]
*
* var bool = ( out === B );
* // returns true
*/
function striu2tril( arrays ) {
	var A = arrays[ 0 ];
	var B = arrays[ 1 ];
	var k = arrays[ 2 ];

	addon( getData( A ), serialize( A ), getData( B ), serialize( B ), getData( k ), serialize( k ) ); // eslint-disable-line max-len
	return B;
}


// EXPORTS //

module.exports = striu2tril;
